package org.springframework.samples.petclinic.rest.function.owner;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits an audit line to the dedicated {@code AUDIT} logger on a successful
 * create, carrying the new owner's id, {@code customerCode},
 * {@code registrationDate} and numeric {@code membershipLevel}.
 *
 * <p>Runs after {@link SaveOwner} (so the id is assigned) and before
 * {@link RespondWithOwnerCreated} in the {@code POST /api/owners} pipeline.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner) {
        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
            owner.getMembershipLevel());
    }
}
===== EnsureCityCapacity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a create-owner request whose {@code city} already contains 50 or more owners,
 * responding 409 via {@link CityAtCapacityException}. Cities are compared
 * case-insensitively, matching {@link AssignCustomerCode}'s per-city grouping.
 *
 * <p>Runs after {@link ValidateOwnerFields} (which publishes the request body) and
 * before {@link BuildOwner} saves anything, so the count it reads excludes the owner
 * being created — the 51st owner in a city is the first one rejected.
 */
public class EnsureCityCapacity {

    private static final int CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        long inCity = ownerRepository.findAll().stream()
            .filter(existing -> city == null
                ? existing.getCity() == null
                : city.equalsIgnoreCase(existing.getCity()))
            .count();
        if (inCity >= CITY_CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }
}
===== ValidatePostcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates the create-owner request's {@code postcode} when one is supplied.
 *
 * <p>Postcode is optional: an absent (or blank) postcode passes untouched, keeping the
 * request contract backward-compatible. When present it must be four digits and, when the
 * owner's city maps to a known region, must fall inside that region's inclusive range per
 * the fixed table (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
 * region accepts any 4-digit postcode. Anything else is rejected with an
 * {@link InvalidPostcodeException} (400). The valid, supplied value is left on the body so
 * {@link BuildOwner} stores and later steps return it.
 */
public class ValidatePostcode {

    /** City -> canonical region, matching the fixed city-to-region table. */
    private static final Map<String, String> CITY_REGION =
            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException("Postcode must be four digits");
        }
        String region = CITY_REGION.get(request.getCity());
        if (region == null) {
            return; // unknown region accepts any 4-digit postcode
        }
        int[] range = REGION_POSTCODES.get(region);
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(
                    "Postcode " + postcode + " is not valid for region " + region);
        }
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Builds the {@link Owner} entity from the request body published by
 * {@link ValidateOwnerFields} (which is the single {@code @RequestBody} reader in the
 * {@code POST /api/owners} pipeline).
 *
 * <p>The registration date is always the effective, business-day-adjusted date resolved
 * by {@link ResolveRegistrationDate} (supplied-or-defaulted, rolled off weekends), so
 * every created owner is persisted (and returned) with a business-day registration date
 * and every value derived from it — such as the membership number's year segment — uses
 * the adjusted date.
 */
public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, @Val LocalDate registrationDate,
            OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        owner.setRegistrationDate(registrationDate);
        built.set(owner);
    }
}
===== ResolveRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Resolves the effective registration date for a create-owner request and publishes it
 * for the rest of the {@code POST /api/owners} pipeline.
 *
 * <p>The effective date is the one supplied in the request body, or the server's
 * current date when the request omits it. Either way it must fall on a business day, so
 * a weekend date is rolled forward to the next Monday (see {@link BusinessDay}). This
 * single adjusted date drives every value derived from the registration date — the
 * per-day create-limit ({@link EnsureDailyCapacity}), the stored registration date and
 * the membership number's year segment ({@link BuildOwner}) — so they all agree.
 *
 * <p>Runs after {@link ValidateOwnerFields} (which publishes the request body) and
 * before {@link EnsureDailyCapacity}.
 */
public class ResolveRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate supplied = request.getRegistrationDate();
        LocalDate effective = supplied != null ? supplied : LocalDate.now();
        registrationDate.set(BusinessDay.roll(effective));
    }
}

